            raise ValueError(
                "reservation %d exceeds total budget %d" % (value, budget)
            )
    admitted = []
    used = sum(active)
    used_slots = len(active)
    for value in waiting:
        if used + value <= budget and used_slots + 1 <= slots:
            admitted.append(value)
            used += value
            used_slots += 1
        else:
            break
    # Admitted is always a prefix of waiting, so slicing keeps
    # duplicate values intact.
    return admitted, waiting[len(admitted):]

