def admit(active, waiting, budget, slots):
    # If any waiting reservation exceeds the total budget, raise ValueError
    for value in waiting:
        if value > budget:
            raise ValueError(f"Reservation {value} exceeds total budget {budget}")

    admitted = []
    current_usage = sum(active)
    current_slots = len(active)

    for value in waiting:
        if current_usage + value <= budget and current_slots + 1 <= slots:
            admitted.append(value)
            current_usage += value
            current_slots += 1
        else:
            break

    remaining = waiting[len(admitted):]
    return admitted, remaining

